  async createDeal(insertDeal: InsertDeal, auditCtx?: { userId?: string | null; actorType?: string; actorId?: string | null }) {
    const { auditChange } = await import("../services/audit-change");
    let payload = { ...insertDeal };
    if (payload.contactId && !payload.partnerOrgId) {
      const [contact] = await db.select({ partnerOrgId: contacts.partnerOrgId }).from(contacts).where(eq(contacts.id, payload.contactId));
      if (contact?.partnerOrgId) payload.partnerOrgId = contact.partnerOrgId;
    }
    return await db.transaction(async (tx) => {
      const [deal] = await tx.insert(deals).values(payload).returning();
      await auditChange({
        userId: auditCtx?.userId ?? null,
        actorType: (auditCtx?.actorType as any) ?? "user",
        actorId: auditCtx?.actorId ?? null,
        action: "deal_created",
        entityType: "deal",
        entityId: deal.id,
        before: null,
        after: deal as unknown as Record<string, unknown>,
      }, tx);
      return deal;
    });
  }


  async updateDeal(id: number, updates: UpdateDealRequest, auditCtx?: { userId?: string | null; actorType?: string; actorId?: string | null }) {
    const { auditChange } = await import("../services/audit-change");
    const [before] = await db.select().from(deals).where(eq(deals.id, id));
    const DEAL_TIMESTAMP_FIELDS: string[] = [
      "nextFollowUp", "expectedGoLiveDate", "goLiveDate", "lastStatementReviewDate",
      "nextStatementReviewDate", "proposalGeneratedAt", "proposalEmailSentAt", "lastNudgeAt",
      "nextNudgeAt", "blueprintGeneratedAt", "closedAt", "boardingSubmittedAt",
      "boardingApprovedAt", "shareLastViewedAt", "archivedAt",
    ];
    const coercedUpdates: Record<string, unknown> = { ...updates };
    for (const field of DEAL_TIMESTAMP_FIELDS) {
      const value = coercedUpdates[field as string];
      if (typeof value === "string") {
        const parsed = new Date(value);
        coercedUpdates[field as string] = isNaN(parsed.getTime()) ? null : parsed;
      }
    }
    return await db.transaction(async (tx) => {
      const [updated] = await tx.update(deals).set({ ...coercedUpdates, updatedAt: new Date() } as typeof deals.$inferInsert).where(eq(deals.id, id)).returning();
      if (updated) {
        await auditChange({
          userId: auditCtx?.userId ?? null,
          actorType: (auditCtx?.actorType as any) ?? "user",
          actorId: auditCtx?.actorId ?? null,
          action: "deal_updated",
          entityType: "deal",
          entityId: id,
          before: before as unknown as Record<string, unknown>,
          after: updated as unknown as Record<string, unknown>,
        }, tx);
      }
      return updated;
    });
  }


  async getDealsStuckInStage(stage: string, maxMinutes: number) {
    const cutoff = new Date(Date.now() - maxMinutes * 60 * 1000);
    return await db.select().from(deals)
      .where(and(
        eq(deals.stage, stage),
        lt(deals.updatedAt!, cutoff),
        isNull(deals.closedAt)
      ));
  }


